// Monta o que a action "triagem" da function robo espera por mensagem:
//   { id, de, assunto, data, message_id, trecho }
//
// O campo que mais importa e o message_id: tem de ser o cabecalho RFC 5322
// (Message-ID), nao o id interno do Gmail. E ele que a pendencia guarda em
// email_message_id e que volta como In-Reply-To/References quando o tecnico
// responde pela tela — sem ele a resposta sai como conversa nova.

const cabecalho = (m, nome) => {
  const alvo = nome.toLowerCase();
  const lista = m.payload?.headers ?? m.headers;
  if (Array.isArray(lista)) {
    const h = lista.find((x) => String(x.name || '').toLowerCase() === alvo);
    return h ? String(h.value || '') : '';
  }
  if (lista && typeof lista === 'object') {
    const k = Object.keys(lista).find((x) => x.toLowerCase() === alvo);
    return k ? String(lista[k] || '') : '';
  }
  return '';
};

// O corpo vem em base64url, as vezes aninhado em multipart/*.
const doBase64 = (s) => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');

const textoSimples = (parte) => {
  if (!parte) return '';
  if (parte.mimeType === 'text/plain' && parte.body?.data) return doBase64(parte.body.data);
  for (const filha of parte.parts ?? []) {
    const t = textoSimples(filha);
    if (t) return t;
  }
  return '';
};

const saida = [];
for (const item of $input.all()) {
  const m = item.json;
  const corpo = textoSimples(m.payload) || String(m.text ?? m.snippet ?? '');
  const dataMs = Number(m.internalDate) || Date.parse(cabecalho(m, 'Date')) || Date.now();
  saida.push({
    json: {
      id: String(m.id || ''),
      de: cabecalho(m, 'From'),
      assunto: cabecalho(m, 'Subject'),
      data: new Date(dataMs).toISOString(),
      message_id: cabecalho(m, 'Message-ID'),
      trecho: corpo.replace(/\r\n/g, '\n').slice(0, 2000),
    },
  });
}
return saida;

// Uma chamada so com todas as mensagens, como o Apps Script faz.
// A function aceita no maximo 100 por chamada (emailsDaEntrada).
const mensagens = $input.all().map((i) => i.json).slice(0, 100);
if (!mensagens.length) return [];  // silencio aqui nao e noticia: nao chama o Intra
return [{ json: { action: 'triagem', mensagens } }];
